diff --git a/libs/connectivitycheck.cpp b/libs/connectivitycheck.cpp
new file mode 100644
index 000000000..b941c9e1f
--- /dev/null
+++ b/libs/connectivitycheck.cpp
@@ -0,0 +1,74 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "connectivitycheck.h"
+
+#include <NetworkManagerQt/Manager>
+
+#include <algorithm>
+#include <chrono>
+
+using namespace std::chrono_literals;
+
+ConnectivityCheck::ConnectivityCheck(QObject *parent)
+    : QObject(parent)
+{
+    // Longer than NetworkManager's own timeout for a check, in case its result never arrives
+    m_timeout.setSingleShot(true);
+    m_timeout.setInterval(30s);
+    connect(&m_timeout, &QTimer::timeout, this, &ConnectivityCheck::update);
+
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::activeConnectionAdded, this, &ConnectivityCheck::addActiveConnection);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::activeConnectionRemoved, this, &ConnectivityCheck::update);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::connectivityChanged, this, &ConnectivityCheck::update);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::isConnectivityCheckEnabledChanged, this, &ConnectivityCheck::update);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::isConnectivityCheckAvailableChanged, this, &ConnectivityCheck::update);
+
+    for (const NetworkManager::ActiveConnection::Ptr &activeConnection : NetworkManager::activeConnections()) {
+        addActiveConnection(activeConnection->path());
+    }
+}
+
+bool ConnectivityCheck::isRunning() const
+{
+    return m_running;
+}
+
+void ConnectivityCheck::addActiveConnection(const QString &path)
+{
+    const NetworkManager::ActiveConnection::Ptr activeConnection = NetworkManager::findActiveConnection(path);
+    if (activeConnection) {
+        connect(activeConnection.data(), &NetworkManager::ActiveConnection::stateChanged, this, &ConnectivityCheck::activeConnectionStateChanged);
+    }
+}
+
+void ConnectivityCheck::activeConnectionStateChanged(NetworkManager::ActiveConnection::State state)
+{
+    if (state == NetworkManager::ActiveConnection::Activated) {
+        m_timeout.start();
+    }
+    update();
+}
+
+void ConnectivityCheck::update()
+{
+    // NetworkManager keeps the previous result until the first check after activation finishes
+    const NetworkManager::Connectivity connectivity = NetworkManager::connectivity();
+    const bool pending = connectivity == NetworkManager::UnknownConnectivity || connectivity == NetworkManager::NoConnectivity;
+    const NetworkManager::ActiveConnection::List activeConnections = NetworkManager::activeConnections();
+    const bool activated = std::any_of(activeConnections.cbegin(), activeConnections.cend(), [](const NetworkManager::ActiveConnection::Ptr &activeConnection) {
+        return activeConnection->state() == NetworkManager::ActiveConnection::Activated;
+    });
+    if (!pending || !activated || !NetworkManager::isConnectivityCheckEnabled() || !NetworkManager::isConnectivityCheckAvailable()) {
+        m_timeout.stop();
+    }
+
+    const bool running = m_timeout.isActive();
+    if (m_running != running) {
+        m_running = running;
+        Q_EMIT runningChanged(running);
+    }
+}
